	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		TimeEntry
	 */
		public TimeEntry createTimeEntry( CreateTimeEntryCommand command ) {

		TimeEntry entity = new TimeEntry();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTimeEntryId( command.getTimeEntryId() );
            entity.setEntryDate( command.getEntryDate() );
            entity.setHoursWorked( command.getHoursWorked() );
            entity.setEntryType( command.getEntryType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of TimeEntry {0} ", entity.toString() );

		return entity;
	}

